/*
 * Rufus TUI implementation using ncurses
 */

#include <ncurses.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <time.h>

#include "tui.h"
#include "../common/rufus.h" // For RUFUS_DRIVE, etc.

// Internal TUI element for rendering
typedef struct {
    int x, y, width, height;
    bool selected, visible, enabled;
    char* label;
    char** options;
    int option_count;
    int selected_index;
    bool is_checkbox;
    bool is_button;
    void* data_ptr;
} tui_control_t;

struct tui_context {
    // ncurses windows
    WINDOW* main_win;
    WINDOW* header_win;
    WINDOW* drives_win;
    WINDOW* options_win;
    WINDOW* progress_win;
    WINDOW* status_win;

    int max_y, max_x;
    int current_focus;
    int num_controls;
    tui_control_t* controls;
    RUFUS_DRIVE* drives;
    int drive_count;
    int selected_drive;
    char status_msg[256];
    int progress;
    char progress_status[128];
    bool initialized;
    // Config state (mirrors Rufus globals)
    char image_path[MAX_PATH];
    int boot_type;
    int partition_scheme;
    int target_system;
    int fs_type;
    int cluster_size;
    char volume_label[128];
    bool quick_format;
    bool bad_blocks;
    int badblocks_passes;
    bool extended_label;
    bool old_bios_fixes;
    bool uefi_validation;
    bool list_hdds;
    bool advanced_device;
    bool advanced_format;
    int image_options;
    uint64_t persistence_size;
    int persistence_units;
};

