    TUI_CTRL_CLUSTER_SIZE,
    TUI_CTRL_VOLUME_LABEL,
    TUI_CTRL_QUICK_FORMAT,
    TUI_CTRL_BAD_BLOCKS,
    TUI_CTRL_BADBLOCKS_PASSES,
    TUI_CTRL_EXTENDED_LABEL,
    TUI_CTRL_OLD_BIOS_FIXES,
    TUI_CTRL_UEFI_VALIDATION,
    TUI_CTRL_LIST_HDDS,
    TUI_CTRL_ADVANCED_DEVICE,
    TUI_CTRL_ADVANCED_FORMAT,
    TUI_CTRL_IMAGE_OPTIONS,
    TUI_CTRL_PERSISTENCE_SIZE,
    TUI_CTRL_PERSISTENCE_UNITS,
    TUI_CTRL_START,
    TUI_CTRL_CANCEL,
    TUI_CTRL_ABOUT,
    TUI_CTRL_LOG,
    TUI_CTRL_SETTINGS,
    TUI_CTRL_LANGUAGE,
    TUI_CTRL_COUNT
};

