// Color initialization
static void init_colors(void) {
    if (has_colors()) {
        start_color();
        use_default_colors();

        init_pair(TUI_COLOR_NORMAL, COLOR_WHITE, -1);
        init_pair(TUI_COLOR_HIGHLIGHT, COLOR_BLACK, COLOR_CYAN);
        init_pair(TUI_COLOR_STATUS, COLOR_WHITE, COLOR_BLUE);
        init_pair(TUI_COLOR_PROGRESS, COLOR_GREEN, -1);
        init_pair(TUI_COLOR_ERROR, COLOR_RED, -1);
        init_pair(TUI_COLOR_DISABLED, COLOR_GRAY, -1);
    }
}

// Draw a single control
static void draw_control(tui_context_t* ctx, int idx) {
    tui_control_t* c = &ctx->controls[idx];
    WINDOW* win = ctx->options_win;
    int y = c->y;

    if (!c->visible)
        return;

    // Set color based on state
    if (c->enabled) {
        if (ctx->current_focus == idx)
            wattron(win, COLOR_PAIR(TUI_COLOR_HIGHLIGHT));
        else
            wattroff(win, COLOR_PAIR(TUI_COLOR_HIGHLIGHT));
    } else {
        wattron(win, COLOR_PAIR(TUI_COLOR_DISABLED));
    }

    // Draw label
    mvwprintw(win, y, c->x, "%s", c->label);

    // Draw value based on type
    int val_x = c->x + 30; // Offset for value area
    if (c->is_checkbox) {
        bool checked = *(bool*)c->data_ptr;
        mvwprintw(win, y, val_x, "[%c]", checked ? 'X' : ' ');
    } else if (c->is_button) {
        wattron(win, A_BOLD);
        mvwprintw(win, y, val_x, "< %s >", c->label);
        wattroff(win, A_BOLD);
    } else if (c->option_count > 0) {
        int sel = *(int*)c->data_ptr;
        if (sel >= 0 && sel < c->option_count) {
            mvwprintw(win, y, val_x, "%s", c->options[sel]);
        }
    } else {
        // Text field
        char* text = (char*)c->data_ptr;
        if (text)
            mvwprintw(win, y, val_x, "%s", text);
    }
}

// Draw the drives window
static void draw_drives_window(tui_context_t* ctx) {
    WINDOW* win = ctx->drives_win;
    werase(win);
    box(win, 0, 0);

    mvwprintw(win, 0, 2, " Available Drives ");

    int start_y = 1;
    int max_items = getmaxy(win) - 2;
    int end_y = getmaxy(win) - 1;

    if (ctx->drive_count == 0) {
        mvwprintw(win, start_y, 2, "No drives found");
        return;
    }

    for (int i = 0; i < ctx->drive_count && i < max_items; i++) {
        RUFUS_DRIVE* d = &ctx->drives[i];
        bool is_selected = (i == ctx->selected_drive);

        if (is_selected)
            wattron(win, COLOR_PAIR(TUI_COLOR_HIGHLIGHT));

        // Format: DriveName (Size) - Label [Media]
        char line[256];
        snprintf(line, sizeof(line), "%d. %s (%s) - %s [%s]",
            i + 1,
            d->device_name ? d->device_name : "Unknown",
            d->size_human ? d->size_human : "0 MB",
            d->volname ? d->volname : "",
            d->media_type == DRIVE_REMOVABLE ? "Removable" : "Fixed");

        // Truncate if needed
        int max_width = getmaxx(win) - 4;
        line[max_width] = '\0';

        mvwprintw(win, start_y + i, 2, "%s", line);

        if (is_selected)
            wattroff(win, COLOR_PAIR(TUI_COLOR_HIGHLIGHT));
    }

    wrefresh(win);
}

// Draw the header window
static void draw_header_window(tui_context_t* ctx) {
    WINDOW* win = ctx->header_win;
    werase(win);

    int rows, cols;
    getmaxyx(win, rows, cols);

    const char* title = "Rufus - USB Formatting Utility (TUI Mode)";
    int title_len = strlen(title);
    int title_x = (cols - title_len) / 2;

    if (title_x < 0) title_x = 0;

    wattron(win, A_BOLD | COLOR_PAIR(TUI_COLOR_STATUS));
    mvwprintw(win, 0, title_x, "%s", title);
    wattroff(win, A_BOLD | COLOR_PAIR(TUI_COLOR_STATUS));

    // Version line
    mvwprintw(win, 1, 2, "v3.xx");

    wrefresh(win);
}

// Draw the options window
static void draw_options_window(tui_context_t* ctx) {
    WINDOW* win = ctx->options_win;
    werase(win);
    box(win, 0, 0);

    int title_y = 0;
    if (ctx->advanced_device) {
        mvwprintw(win, title_y, 2, " Device Properties (Advanced) ");
    } else {
        mvwprintw(win, title_y, 2, " Configuration Options ");
    }

    // Draw each visible control
    for (int i = 0; i < ctx->num_controls; i++) {
        draw_control(ctx, i);
    }

    wrefresh(win);
}

// Draw the progress window
static void draw_progress_window(tui_context_t* ctx) {
    WINDOW* win = ctx->progress_win;
    werase(win);

    int rows, cols;
    getmaxyx(win, rows, cols);

    int y = 0;
    mvwprintw(win, y++, 1, " Progress: ");

    // Progress bar
    int bar_width = cols - 2;
    int filled = (ctx->progress * bar_width) / 100;

    for (int i = 0; i < bar_width; i++) {
        if (i < filled)
            mvwaddch(win, y, 1 + i, ACS_CKBOARD);
        else
            mvwaddch(win, y, 1 + i, ' ');
    }

    mvwprintw(win, y, 1, "%3d%%", ctx->progress);

    // Status line
    y += 2;
    if (ctx->progress_status[0]) {
        mvwprintw(win, y++, 1, "%s", ctx->progress_status);
    }

    wrefresh(win);
}

// Draw the status window
static void draw_status_window(tui_context_t* ctx) {
    WINDOW* win = ctx->status_win;
    werase(win);

    int rows, cols;
    getmaxyx(win, rows, cols);

    // Left side: status message
    if (ctx->status_msg[0]) {
        wattron(win, COLOR_PAIR(TUI_COLOR_STATUS));
        mvwprintw(win, 0, 1, "%s", ctx->status_msg);
        wattroff(win, COLOR_PAIR(TUI_COLOR_STATUS));
    }

    // Right side: help hint
    const char* help = "F1=Help  F10=Quit  Enter=Select  Space=Toggle  Tab=Next";
    int help_len = strlen(help);
    mvwprintw(win, 0, cols - help_len - 1, "%s", help);

    wrefresh(win);
}

