// Main refresh function
static void tui_do_refresh(tui_context_t* ctx) {
    draw_header_window(ctx);
    draw_drives_window(ctx);
    draw_options_window(ctx);
    draw_progress_window(ctx);
    draw_status_window(ctx);
    wnoutrefresh(ctx->main_win);
    doupdate();
}

// Calculate layout
static void calculate_layout(tui_context_t* ctx) {
    int rows, cols;
    getmaxyx(stdscr, rows, cols);
    ctx->max_y = rows;
    ctx->max_x = cols;

    if (ctx->main_win) {
        delwin(ctx->main_win);
        delwin(ctx->header_win);
        delwin(ctx->drives_win);
        delwin(ctx->options_win);
        delwin(ctx->progress_win);
        delwin(ctx->status_win);
    }

    // Main window (full screen)
    ctx->main_win = newwin(rows, cols, 0, 0);

    // Header (top 2 lines)
    ctx->header_win = derwin(ctx->main_win, 2, cols, 0, 0);

    // Drives panel (left side, height - 8)
    int drive_h = rows - 8;
    if (drive_h < 5) drive_h = 5;
    ctx->drives_win = derwin(ctx->main_win, drive_h, 35, 2, 0);

    // Options panel (right side)
    int opt_h = rows - 8;
    int opt_w = cols - 37;
    if (opt_w < 40) opt_w = 40;
    ctx->options_win = derwin(ctx->main_win, opt_h, opt_w, 2, 36);

    // Progress panel (bottom)
    ctx->progress_win = derwin(ctx->main_win, 5, cols, rows - 5, 0);

    // Status panel (bottom line)
    ctx->status_win = derwin(ctx->main_win, 1, cols, rows - 1, 0);

    // Reinitialize controls with new positions
    free(ctx->controls);
    ctx->controls = NULL;
    init_controls(ctx);
}

// Public functions implementation
bool tui_init(tui_context_t* ctx) {
    if (!ctx) return false;

    memset(ctx, 0, sizeof(tui_context_t));
    ctx->initialized = false;

    // Initialize ncurses
    initscr();
    cbreak();
    noecho();
    keypad(stdscr, TRUE);
    curs_set(0);
    start_color();
    use_default_colors();

    init_colors();

    // Store context pointer as a global (simplified)
    ctx->main_win = stdscr;
    ctx->initialized = true;

    // Calculate layout
    calculate_layout(ctx);

    // Initial control positions
    for (int i = 0; i < ctx->num_controls; i++) {
        ctx->controls[i].x = 2;
        ctx->controls[i].y = 2 + i * 2;
    }

    // Default configuration
    ctx->boot_type = 1; // ISO/IMG
    ctx->partition_scheme = 0; // MBR
    ctx->target_system = 1; // UEFI
    ctx->fs_type = 2; // NTFS
    ctx->cluster_size = 3; // Default 4096
    ctx->quick_format = true;
    ctx->bad_blocks = false;
    ctx->badblocks_passes = 1;
    ctx->extended_label = false;
    ctx->old_bios_fixes = true;
    ctx->uefi_validation = true;
    ctx->image_options = 0; // Standard
    ctx->selected_drive = -1;

    strncpy(ctx->volume_label, "RUFUS", sizeof(ctx->volume_label) - 1);

    tui_do_refresh(ctx);

    return true;
}

void tui_shutdown(tui_context_t* ctx) {
    if (ctx && ctx->initialized) {
        if (ctx->controls) free(ctx->controls);
        endwin();
        ctx->initialized = false;
    }
}

int tui_run(tui_context_t* ctx) {
    if (!ctx || !ctx->initialized) return -1;

    ctx->current_focus = 0;

    while (1) {
        tui_do_refresh(ctx);

        int ch = getch();

        // Handle global keys
        if (ch == KEY_F(10) || ch == 'q' || ch == 'Q') {
            return TUI_CTRL_CANCEL;
        }
        if (ch == KEY_F(1) || ch == '?') {
            tui_message(ctx, "Help", "Rufus TUI - Use arrow keys to navigate, Enter to select, Space to toggle.", false);
            continue;
        }
        if (ch == '\n' || ch == '\r') {
            int focused = ctx->current_focus;
            if (focused >= 0 && focused < ctx->num_controls) {
                tui_control_t* c = &ctx->controls[focused];
                if (c->is_button) {
                    return focused;
                } else if (c->option_count > 0) {
                    // Cycle option
                    int* val = (int*)c->data_ptr;
                    (*val)++;
                    if (*val >= c->option_count) *val = 0;
                } else if (c->is_checkbox) {
                    bool* val = (bool*)c->data_ptr;
                    *val = !(*val);
                    // Update dependent controls
                    if (strcmp(c->label, "Check for bad blocks") == 0) {
                        ctx->controls[TUI_CTRL_BADBLOCKS_PASSES].visible = *val;
                        ctx->controls[TUI_CTRL_BADBLOCKS_PASSES].enabled = *val;
                    } else if (strcmp(c->label, "Image Options:") == 0) {
                        bool show_persist = (*val == 1);
                        ctx->controls[TUI_CTRL_PERSISTENCE_SIZE].visible = show_persist;
                        ctx->controls[TUI_CTRL_PERSISTENCE_SIZE].enabled = show_persist;
                        ctx->controls[TUI_CTRL_PERSISTENCE_UNITS].visible = show_persist;
                        ctx->controls[TUI_CTRL_PERSISTENCE_UNITS].enabled = show_persist;
                    }
                }
            }
            continue;
        }
        if (ch == ' ') {
            int focused = ctx->current_focus;
            if (focused >= 0 && focused < ctx->num_controls) {
                tui_control_t* c = &ctx->controls[focused];
                if (c->is_checkbox) {
                    bool* val = (bool*)c->data_ptr;
                    *val = !(*val);
                }
            }
            continue;
        }
        if (ch == '\t' || ch == KEY_RIGHT) {
            // Move to next control
            do {
                ctx->current_focus++;
                if (ctx->current_focus >= ctx->num_controls)
                    ctx->current_focus = 0;
            } while (!ctx->controls[ctx->current_focus].visible);
            continue;
        }
        if (ch == KEY_LEFT) {
            // Move to previous control
            do {
                if (ctx->current_focus <= 0)
                    ctx->current_focus = ctx->num_controls - 1;
                else
                    ctx->current_focus--;
            } while (!ctx->controls[ctx->current_focus].visible);
            continue;
        }
        if (ch == KEY_UP) {
            // Select previous drive
            if (ctx->drive_count > 0) {
                if (ctx->selected_drive > 0)
                    ctx->selected_drive--;
                else
                    ctx->selected_drive = ctx->drive_count - 1;
                // Update drive selection in config
                // (In real integration, would sync with RUFUS_DRIVE)
            }
            continue;
        }
        if (ch == KEY_DOWN) {
            // Select next drive
            if (ctx->drive_count > 0) {
                ctx->selected_drive++;
                if (ctx->selected_drive >= ctx->drive_count)
                    ctx->selected_drive = 0;
            }
            continue;
        }
        if (ch >= '1' && ch <= '9') {
            // Quick drive selection
            int idx = ch - '1';
            if (idx < ctx->drive_count) {
                ctx->selected_drive = idx;
            }
            continue;
        }

        // Pass other keys to regular input (for text fields)
        if (ch > 31 && ch < 256) {
            int focused = ctx->current_focus;
            if (focused >= 0 && focused < ctx->num_controls) {
                tui_control_t* c = &ctx->controls[focused];
                if (!c->is_checkbox && !c->is_button && c->option_count == 0) {
                    // Text field - append character
                    char* text = (char*)c->data_ptr;
                    int len = strlen(text);
                    if (len < c->width - 2) {
                        text[len] = ch;
                        text[len + 1] = '\0';
                    }
                }
            }
            continue;
        }
    }

    return -1;
}

