void tui_message(tui_context_t* ctx, const char* title, const char* message, bool error) {
    if (!ctx || !ctx->initialized) return;

    int rows, cols;
    getmaxyx(stdscr, rows, cols);

    // Create popup window
    WINDOW* popup = newwin(10, 60, (rows-10)/2, (cols-60)/2);
    box(popup, 0, 0);

    if (title) {
        wattron(popup, A_BOLD);
        mvwprintw(popup, 0, (60 - strlen(title))/2, "%s", title);
        wattroff(popup, A_BOLD);
    }

    // Display message (wrap lines)
    int y = 2;
    int x = 2;
    for (const char* p = message; *p && y < 8; ) {
        char line[50];
        int i = 0;
        while (i < 45 && *p && *p != '\n') {
            line[i++] = *p++;
        }
        line[i] = '\0';
        mvwprintw(popup, y, x, "%s", line);
        y++;
        if (*p == '\n') p++;
    }

    mvwprintw(popup, 9, 20, "< OK >");
    wrefresh(popup);

    // Wait for Enter or any key
    while (getch() != '\n' && getch() != '\r' && getch() != ' ' && getch() != KEY_F(10));

    delwin(popup);
    tui_do_refresh(ctx);
}

void tui_update_progress(tui_context_t* ctx, int percentage, const char* status) {
    if (!ctx) return;
    if (percentage >= 0 && percentage <= 100)
        ctx->progress = percentage;
    if (status)
        strncpy(ctx->progress_status, status, sizeof(ctx->progress_status) - 1);
    tui_refresh(ctx);
}

void tui_set_drives(tui_context_t* ctx, void* drives, int count, int selected) {
    if (!ctx) return;
    ctx->drives = (RUFUS_DRIVE*)drives;
    ctx->drive_count = count;
    ctx->selected_drive = selected;
}

